#!/usr/bin/env ts-node
/**
 * DLQ Management CLI
 * Command-line utility for inspecting and managing the dead letter queue
 *
 * Usage:
 *   pnpm dlq:stats              - Show DLQ statistics
 *   pnpm dlq:list [limit]       - List DLQ jobs (default: 20)
 *   pnpm dlq:inspect <jobId>    - Inspect specific job details
 *   pnpm dlq:retry <jobId>      - Retry a specific job
 *   pnpm dlq:retry-all [limit]  - Retry all DLQ jobs (default: 100)
 *   pnpm dlq:purge [days]       - Purge jobs older than N days (default: 30)
 */

import 'dotenv/config';
import {
  getDLQJobs,
  getDLQStats,
  retryDLQJob,
  retryAllDLQJobs,
  purgeDLQEntries,
  inspectDLQJob,
} from '../src/lib/dlq';
import { closeQueues } from '../src/queue';

const command = process.argv[2];
const arg1 = process.argv[3];

async function main() {
  try {
    switch (command) {
      case 'stats': {
        const stats = await getDLQStats();
        console.log('\n📊 DLQ Statistics:');
        console.log(`Total jobs: ${stats.total}`);
        console.log(`Waiting: ${stats.waiting}`);
        console.log(`Active: ${stats.active}`);
        console.log(`Completed: ${stats.completed}`);
        console.log('\nFailures by reason:');
        Object.entries(stats.failuresByReason).forEach(([reason, count]) => {
          console.log(`  ${reason}: ${count}`);
        });
        break;
      }

      case 'list': {
        const limit = arg1 ? parseInt(arg1, 10) : 20;
        const jobs = await getDLQJobs(limit);
        console.log(`\n📋 DLQ Jobs (showing ${jobs.length}):\n`);

        if (jobs.length === 0) {
          console.log('  No jobs in DLQ ✅');
        } else {
          jobs.forEach((job, idx) => {
            console.log(`${idx + 1}. Job ID: ${job.id}`);
            console.log(`   Workspace: ${job.data.workspaceId}`);
            console.log(`   Ingestion ID: ${job.data.ingestionId || 'N/A'}`);
            console.log(`   Failed Reason: ${job.failedReason || 'unknown'}`);
            console.log(`   Attempts: ${job.attemptsMade || 'N/A'}`);
            console.log(`   Timestamp: ${new Date(job.timestamp).toISOString()}`);
            console.log('');
          });
        }
        break;
      }

      case 'inspect': {
        if (!arg1) {
          console.error('❌ Job ID required');
          process.exit(1);
        }

        const details = await inspectDLQJob(arg1);
        if (!details) {
          console.error(`❌ Job not found: ${arg1}`);
          process.exit(1);
        }

        console.log('\n🔍 Job Details:\n');
        console.log(JSON.stringify(details, null, 2));
        break;
      }

      case 'retry': {
        if (!arg1) {
          console.error('❌ Job ID required');
          process.exit(1);
        }

        console.log(`🔄 Retrying job ${arg1}...`);
        const result = await retryDLQJob(arg1);

        if (result.success) {
          console.log(`✅ Job retried successfully. New job ID: ${result.newJobId}`);
        } else {
          console.error('❌ Failed to retry job');
          process.exit(1);
        }
        break;
      }

      case 'retry-all': {
        const maxJobs = arg1 ? parseInt(arg1, 10) : 100;
        console.log(`🔄 Retrying up to ${maxJobs} DLQ jobs...`);

        const result = await retryAllDLQJobs(maxJobs);
        console.log(`\n✅ Retry completed:`);
        console.log(`   Attempted: ${result.attempted}`);
        console.log(`   Succeeded: ${result.succeeded}`);
        console.log(`   Failed: ${result.failed}`);
        break;
      }

      case 'purge': {
        const days = arg1 ? parseInt(arg1, 10) : 30;
        console.log(`🗑️  Purging DLQ entries older than ${days} days...`);

        const purged = await purgeDLQEntries(days);
        console.log(`✅ Purged ${purged} entries`);
        break;
      }

      default: {
        console.log(`
DLQ Management CLI

Usage:
  pnpm dlq:stats              - Show DLQ statistics
  pnpm dlq:list [limit]       - List DLQ jobs (default: 20)
  pnpm dlq:inspect <jobId>    - Inspect specific job details
  pnpm dlq:retry <jobId>      - Retry a specific job
  pnpm dlq:retry-all [limit]  - Retry all DLQ jobs (default: 100)
  pnpm dlq:purge [days]       - Purge jobs older than N days (default: 30)

Examples:
  pnpm dlq:stats
  pnpm dlq:list 50
  pnpm dlq:inspect job-123
  pnpm dlq:retry job-123
  pnpm dlq:retry-all 200
  pnpm dlq:purge 60
        `);
        process.exit(command ? 1 : 0);
      }
    }
  } catch (error) {
    console.error('❌ Error:', error);
    process.exit(1);
  } finally {
    await closeQueues();
    process.exit(0);
  }
}

main();

/**
 * Test Upstash QStash connection
 * Run with: npx ts-node scripts/test-qstash.ts
 */

import 'dotenv/config';

async function testQStash() {
  console.log('🔍 Testing Upstash QStash connection...\n');

  const token = process.env.QSTASH_TOKEN;
  const currentSigningKey = process.env.QSTASH_CURRENT_SIGNING_KEY;
  const nextSigningKey = process.env.QSTASH_NEXT_SIGNING_KEY;

  if (!token) {
    console.error('❌ QSTASH_TOKEN not set');
    process.exit(1);
  }

  console.log(`  Token: ${token.substring(0, 20)}...`);
  console.log(
    `  Current Signing Key: ${currentSigningKey ? currentSigningKey.substring(0, 10) + '...' : 'not set'}`,
  );
  console.log(
    `  Next Signing Key: ${nextSigningKey ? nextSigningKey.substring(0, 10) + '...' : 'not set'}`,
  );

  try {
    // Import QStash client
    const { Client } = await import('@upstash/qstash');

    const client = new Client({
      token: token.replace(/"/g, ''),
    });

    // Test: List schedules (this verifies the connection)
    console.log('\n📋 Testing connection by listing schedules...');
    const schedules = await client.schedules.list();
    console.log(`  ✅ Connected! Found ${schedules.length} existing schedule(s)`);

    // Test: Publish a message to a test URL (using httpbin as echo service)
    console.log('\n📤 Testing message publishing...');
    const testUrl = 'https://httpbin.org/post';

    const result = await client.publishJSON({
      url: testUrl,
      body: {
        test: true,
        message: 'Hello from Soft Systems Studio QStash test!',
        timestamp: new Date().toISOString(),
      },
    });

    console.log(`  ✅ Message published!`);
    console.log(`     Message ID: ${result.messageId}`);

    // Test: Get message status (optional, may take a moment to process)
    console.log('\n📊 Message has been queued for delivery to:', testUrl);
    console.log('   (QStash will retry automatically if delivery fails)');

    // Test Receiver setup (for webhook verification)
    if (currentSigningKey && nextSigningKey) {
      console.log('\n🔐 Testing Receiver setup...');
      const { Receiver } = await import('@upstash/qstash');

      const receiver = new Receiver({
        currentSigningKey: currentSigningKey.replace(/"/g, ''),
        nextSigningKey: nextSigningKey.replace(/"/g, ''),
      });

      // Verify receiver is properly initialized
      console.log(`  ✅ Receiver initialized (ready to verify webhook signatures)`);
      void receiver; // Use receiver to satisfy noUnusedLocals
    }

    console.log('\n✅ All QStash tests passed!\n');
    console.log('Your QStash is ready for:');
    console.log('  • Background job processing');
    console.log('  • Scheduled tasks (cron jobs)');
    console.log('  • Webhook delivery with retries');
    console.log('  • Delayed message processing');

    console.log('\n📝 Example usage:');
    console.log(`
// Publish a background job
await client.publishJSON({
  url: 'https://your-api.com/api/webhooks/process-email',
  body: { userId: '123', action: 'send-welcome' },
  delay: 60, // delay 60 seconds
  retries: 3,
});

// Schedule a recurring job
await client.schedules.create({
  destination: 'https://your-api.com/api/cron/daily-cleanup',
  cron: '0 9 * * *', // Every day at 9am
});
`);
  } catch (error) {
    console.error('\n❌ QStash test failed:', error);
    process.exit(1);
  }
}

testQStash();

/**
 * Test script for Sentry backend integration
 *
 * Run with: npx ts-node --transpile-only scripts/test-sentry.ts
 */

import * as Sentry from '@sentry/node';
import dotenv from 'dotenv';

// Load environment variables
dotenv.config();

const dsn = process.env.SENTRY_DSN;

if (!dsn) {
  console.error('❌ SENTRY_DSN is not set in .env');
  process.exit(1);
}

console.log('🔧 Initializing Sentry...');
console.log(`   DSN: ${dsn.substring(0, 30)}...`);
console.log(`   Environment: ${process.env.SENTRY_ENVIRONMENT || 'development'}`);

// Initialize Sentry for testing
Sentry.init({
  dsn,
  environment: process.env.SENTRY_ENVIRONMENT || 'development',
  tracesSampleRate: 1.0,
  debug: true, // Enable debug mode to see what's happening
});

async function testSentry() {
  console.log('\n📤 Sending test error to Sentry...');

  try {
    // Capture a test exception
    const eventId = Sentry.captureException(
      new Error('Test error from backend Sentry test script'),
    );
    console.log(`   Event ID: ${eventId}`);

    // Capture a test message
    const messageId = Sentry.captureMessage('Test message from backend Sentry test script', 'info');
    console.log(`   Message ID: ${messageId}`);

    // Flush to ensure events are sent
    console.log('\n⏳ Flushing events to Sentry...');
    await Sentry.flush(5000);

    console.log('\n✅ Sentry test completed!');
    console.log('   Check your Sentry dashboard for:');
    console.log('   - "Test error from backend Sentry test script"');
    console.log('   - "Test message from backend Sentry test script"');
    console.log(
      `\n   Dashboard: https://sentry.io/organizations/${process.env.SENTRY_ORG || 'your-org'}/issues/`,
    );
  } catch (error) {
    console.error('❌ Error during Sentry test:', error);
  }
}

testSentry();

/**
 * Test script for Stripe integration
 * Run with: npx tsx scripts/test-stripe.ts
 */
import 'dotenv/config';

async function testStripe() {
  console.log('🔧 Testing Stripe Integration...\n');

  // Check environment variables
  const secretKey = process.env.STRIPE_SECRET_KEY;
  const webhookSecret = process.env.STRIPE_WEBHOOK_SECRET;

  console.log('📋 Environment Variables:');
  console.log(
    `  STRIPE_SECRET_KEY: ${secretKey ? `${secretKey.substring(0, 12)}...` : '❌ NOT SET'}`,
  );
  console.log(
    `  STRIPE_WEBHOOK_SECRET: ${webhookSecret ? `${webhookSecret.substring(0, 12)}...` : '❌ NOT SET'}`,
  );

  if (!secretKey || secretKey.includes('YOUR_SECRET_KEY')) {
    console.log('\n❌ STRIPE_SECRET_KEY is not configured properly.');
    console.log('   Get your key from: https://dashboard.stripe.com/apikeys');
    process.exit(1);
  }

  console.log('\n🔌 Testing Stripe API connection...');

  try {
    const Stripe = (await import('stripe')).default;
    const stripe = new Stripe(secretKey, {
      typescript: true,
      appInfo: {
        name: 'Soft Systems Studio Test',
        version: '1.0.0',
      },
    });

    // Test 1: Fetch account info
    console.log('\n📊 Test 1: Fetching account info...');
    const account = await stripe.accounts.retrieve();
    console.log(`  ✅ Connected to Stripe account`);
    console.log(`     Account ID: ${account.id}`);
    console.log(`     Country: ${account.country}`);
    console.log(`     Default Currency: ${account.default_currency?.toUpperCase()}`);

    // Test 2: List products
    console.log('\n📦 Test 2: Listing products...');
    const products = await stripe.products.list({ limit: 5 });
    if (products.data.length > 0) {
      console.log(`  ✅ Found ${products.data.length} product(s):`);
      products.data.forEach((p) => {
        console.log(`     - ${p.name} (${p.id})`);
      });
    } else {
      console.log('  ℹ️  No products found (this is OK for new accounts)');
    }

    // Test 3: List prices
    console.log('\n💰 Test 3: Listing prices...');
    const prices = await stripe.prices.list({ limit: 5, active: true });
    if (prices.data.length > 0) {
      console.log(`  ✅ Found ${prices.data.length} price(s):`);
      prices.data.forEach((p) => {
        const amount = p.unit_amount ? (p.unit_amount / 100).toFixed(2) : 'N/A';
        const interval = p.recurring?.interval || 'one-time';
        console.log(`     - ${p.id}: $${amount} ${p.currency.toUpperCase()} (${interval})`);
      });
    } else {
      console.log('  ℹ️  No prices found (create products in Stripe Dashboard)');
    }

    // Test 4: List customers
    console.log('\n👥 Test 4: Listing recent customers...');
    const customers = await stripe.customers.list({ limit: 3 });
    if (customers.data.length > 0) {
      console.log(`  ✅ Found ${customers.data.length} customer(s):`);
      customers.data.forEach((c) => {
        console.log(`     - ${c.email || 'No email'} (${c.id})`);
      });
    } else {
      console.log('  ℹ️  No customers found yet');
    }

    // Test 5: Check webhook endpoint (if secret is set)
    if (webhookSecret && !webhookSecret.includes('YOUR_WEBHOOK_SECRET')) {
      console.log('\n🔐 Test 5: Webhook secret configured');
      console.log('  ✅ Webhook secret is set');
      console.log('  ℹ️  To test webhooks, use Stripe CLI:');
      console.log('     stripe listen --forward-to localhost:5000/api/v1/stripe/webhook');
    } else {
      console.log('\n⚠️  Test 5: Webhook secret not configured');
      console.log('  Set STRIPE_WEBHOOK_SECRET after creating webhook endpoint');
    }

    console.log('\n✅ All Stripe tests passed!\n');
    console.log('Your Stripe integration is ready for:');
    console.log('  • Creating checkout sessions');
    console.log('  • Managing subscriptions');
    console.log('  • Processing payments');
    console.log('  • Handling webhooks');
  } catch (error) {
    const err = error as Error & { type?: string; code?: string };
    console.error('\n❌ Stripe test failed:', err.message);

    if (err.type === 'StripeAuthenticationError') {
      console.log('\n💡 Your API key appears to be invalid.');
      console.log('   Make sure you copied the full key from Stripe Dashboard.');
    } else if (err.code === 'ENOTFOUND') {
      console.log('\n💡 Network error - check your internet connection.');
    }

    process.exit(1);
  }
}

testStripe();

/**
 * Test Upstash Redis connection
 * Run with: npx ts-node scripts/test-upstash.ts
 */

import 'dotenv/config';

async function testUpstash() {
  console.log('🔍 Testing Upstash Redis connection...\n');

  const url = process.env.UPSTASH_REDIS_REST_URL;
  const token = process.env.UPSTASH_REDIS_REST_TOKEN;

  if (!url || !token) {
    console.error('❌ UPSTASH_REDIS_REST_URL or UPSTASH_REDIS_REST_TOKEN not set');
    process.exit(1);
  }

  console.log(`  URL: ${url}`);
  console.log(`  Token: ${token.substring(0, 10)}...`);

  try {
    // Import Upstash Redis
    const { Redis } = await import('@upstash/redis');

    const redis = new Redis({
      url: url.replace(/"/g, ''), // Remove any quotes
      token: token.replace(/"/g, ''),
    });

    // Test PING
    console.log('\n📡 Testing PING...');
    const pong = await redis.ping();
    console.log(`  ✅ PING response: ${pong}`);

    // Test SET
    console.log('\n📝 Testing SET...');
    await redis.set('test:connection', 'Hello from Soft Systems Studio!');
    console.log('  ✅ SET successful');

    // Test GET
    console.log('\n📖 Testing GET...');
    const value = await redis.get('test:connection');
    console.log(`  ✅ GET response: ${value}`);

    // Test INCR (for rate limiting)
    console.log('\n🔢 Testing INCR (rate limiting simulation)...');
    const count = await redis.incr('test:counter');
    console.log(`  ✅ Counter value: ${count}`);

    // Test EXPIRE
    console.log('\n⏰ Testing EXPIRE...');
    await redis.expire('test:counter', 60);
    const ttl = await redis.ttl('test:counter');
    console.log(`  ✅ TTL set: ${ttl} seconds`);

    // Cleanup
    console.log('\n🧹 Cleaning up test keys...');
    await redis.del('test:connection', 'test:counter');
    console.log('  ✅ Cleanup complete');

    console.log('\n✅ All Upstash Redis tests passed!\n');
    console.log('Your Upstash Redis is ready for:');
    console.log('  • Caching');
    console.log('  • Rate limiting');
    console.log('  • Session storage');
    console.log('  • Queue state management');
  } catch (error) {
    console.error('\n❌ Upstash Redis test failed:', error);
    process.exit(1);
  }
}

testUpstash();

