/**
 * Chat Controller
 * Handles chat endpoint logic with RAG retrieval and conversation persistence
 */
import type { Request, Response } from 'express';
import type { ChatRequest } from '../schemas/chat';
import { getRequestLogger } from '../middleware/requestContext';
import { runChat } from '../services/chat';

/**
 * Extended request type with auth context
 */
interface AuthRequest extends Request {
  auth?: {
    workspaceId?: string;
    userId?: string;
  };
  validatedBody?: ChatRequest;
}

/**
 * Chat controller - handles customer service chat with RAG retrieval
 * Expects authentication and workspace context from middleware
 */
export async function chatController(req: Request, res: Response) {
  const authReq = req as AuthRequest;
  const log = getRequestLogger(req); // Use request-bound logger with context

  // Get validated body from middleware or fallback to req.body
  const payload = authReq.validatedBody ?? (authReq.body as ChatRequest);
  const workspaceId = authReq.auth?.workspaceId;
  const userId = authReq.auth?.userId;

  // This should never happen due to requireWorkspace middleware, but TypeScript needs it
  if (!workspaceId) {
    return res.status(401).json({
      error: 'workspace_required',
      message: 'Workspace context is required for chat operations',
    });
  }

  try {
    log.info(
      {
        messageLength: payload.message.length,
        hasConversationId: !!payload.conversationId,
      },
      'Chat request received',
    );

    // Run chat with RAG retrieval and persistence
    const result = await runChat({
      workspaceId,
      message: payload.message,
      userId,
      conversationId: payload.conversationId,
    });

    log.info(
      {
        conversationId: result.conversationId,
        messageIds: result.messageIds,
      },
      'Chat completed successfully',
    );

    // Return reply with conversation context
    return res.status(200).json({
      reply: result.reply,
      conversationId: result.conversationId,
    });
  } catch (err) {
    log.error(
      {
        err,
      },
      'Chat controller failed',
    );

    return res.status(500).json({
      error: 'CHAT_FAILED',
      message: err instanceof Error ? err.message : 'Failed to process chat request',
    });
  }
}

import type { Request, Response } from 'express';
import type { RunRequest } from '../schemas/run';
import { logger } from '../logger';
import { runChat } from '../services/runChat';

export async function runController(req: Request, res: Response) {
  // Prefer validatedBody if middleware attaches it, otherwise fall back to req.body
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const body = ((req as any).validatedBody as RunRequest) ?? (req.body as RunRequest);

  try {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const principal = (req as any).authPrincipal;

    const result = await runChat({
      workspaceId: body.workspaceId,
      agentId: body.agentId,
      input: body.input,
      stream: body.stream ?? false,
      principal: {
        userId: principal?.userId,
        workspaceId: body.workspaceId,
        roles: principal?.roles,
      },
      requestId: (req as any).requestId,
    });

    const statusCode = result.statusCode ?? (result.status === 'completed' ? 200 : 202);
    return res
      .status(statusCode)
      .json({ runId: result.runId, status: result.status, reply: result.reply });
  } catch (err) {
    logger.error({ err }, 'runController failed');
    return res.status(500).json({
      error: 'RUN_FAILED',
      message: err instanceof Error ? err.message : 'Unknown error',
    });
  }
}

/**
 * Dead Letter Queue Management
 * Utilities for inspecting and recovering from failed ingestion jobs
 */
import { ingestDLQ, ingestQueue, type IngestJobData } from '../queue';
import { logger } from '../logger';

export interface DLQJob {
  id: string;
  data: IngestJobData;
  timestamp: number;
  failedReason?: string;
  attemptsMade?: number;
}

/**
 * Get all jobs in the DLQ
 */
export async function getDLQJobs(limit = 100): Promise<DLQJob[]> {
  const jobs = await ingestDLQ.getJobs(['waiting', 'active', 'completed'], 0, limit - 1);

  return jobs.map((job) => ({
    id: job.id || 'unknown',
    data: job.data,
    timestamp: job.timestamp,
    failedReason: job.data.metadata?.failedReason as string | undefined,
    attemptsMade: job.data.metadata?.attemptsMade as number | undefined,
  }));
}

/**
 * Get DLQ statistics
 */
export async function getDLQStats() {
  const counts = await ingestDLQ.getJobCounts();
  const jobs = await getDLQJobs(1000);

  // Count failures by reason
  const failuresByReason: Record<string, number> = {};
  jobs.forEach((job) => {
    const reason = job.failedReason || 'unknown';
    failuresByReason[reason] = (failuresByReason[reason] || 0) + 1;
  });

  return {
    total: jobs.length,
    waiting: counts.waiting || 0,
    active: counts.active || 0,
    completed: counts.completed || 0,
    failuresByReason,
  };
}

/**
 * Retry a specific job from the DLQ
 * Removes the original DLQ entry and re-queues to main queue
 */
export async function retryDLQJob(jobId: string): Promise<{ success: boolean; newJobId?: string }> {
  const job = await ingestDLQ.getJob(jobId);

  if (!job) {
    logger.warn({ jobId }, 'DLQ job not found');
    return { success: false };
  }

  try {
    // Extract original job data (without DLQ metadata)
    const { metadata, ...originalData } = job.data;
    const cleanData: IngestJobData = {
      ...originalData,
      metadata: metadata
        ? Object.fromEntries(
            Object.entries(metadata).filter(
              ([key]) =>
                !['originalJobId', 'failedReason', 'attemptsMade', 'failedAt'].includes(key),
            ),
          )
        : undefined,
    };

    // Re-queue to main ingest queue
    const newJob = await ingestQueue.add('retry', cleanData, {
      priority: 1, // Higher priority for retries
    });

    // Remove from DLQ
    await job.remove();

    logger.info(
      {
        dlqJobId: jobId,
        newJobId: newJob.id,
        workspaceId: cleanData.workspaceId,
      },
      'DLQ job re-queued successfully',
    );

    return { success: true, newJobId: newJob.id };
  } catch (error) {
    logger.error({ jobId, error }, 'Failed to retry DLQ job');
    return { success: false };
  }
}

/**
 * Retry all jobs in the DLQ
 * Use with caution - may cause load spike
 */
export async function retryAllDLQJobs(maxJobs = 100): Promise<{
  attempted: number;
  succeeded: number;
  failed: number;
}> {
  const jobs = await getDLQJobs(maxJobs);

  let succeeded = 0;
  let failed = 0;

  logger.info({ totalJobs: jobs.length }, 'Starting bulk DLQ retry');

  for (const job of jobs) {
    const result = await retryDLQJob(job.id);
    if (result.success) {
      succeeded++;
    } else {
      failed++;
    }

    // Add small delay to avoid overwhelming the system
    await new Promise((resolve) => setTimeout(resolve, 100));
  }

  logger.info({ attempted: jobs.length, succeeded, failed }, 'Bulk DLQ retry completed');

  return {
    attempted: jobs.length,
    succeeded,
    failed,
  };
}

/**
 * Purge old DLQ entries (for jobs that can't be recovered)
 * @param olderThanDays - Remove entries older than this many days
 */
export async function purgeDLQEntries(olderThanDays = 30): Promise<number> {
  const jobs = await getDLQJobs(10000);
  const cutoffTime = Date.now() - olderThanDays * 24 * 60 * 60 * 1000;

  let purged = 0;

  for (const job of jobs) {
    if (job.timestamp < cutoffTime) {
      const fullJob = await ingestDLQ.getJob(job.id);
      if (fullJob) {
        await fullJob.remove();
        purged++;
      }
    }
  }

  logger.info({ purged, olderThanDays }, 'DLQ entries purged');

  return purged;
}

/**
 * Get detailed information about a specific DLQ job
 */
export async function inspectDLQJob(jobId: string) {
  const job = await ingestDLQ.getJob(jobId);

  if (!job) {
    return null;
  }

  return {
    id: job.id,
    data: job.data,
    timestamp: job.timestamp,
    processedOn: job.processedOn,
    finishedOn: job.finishedOn,
    attemptsMade: job.attemptsMade,
    failedReason: job.failedReason,
    stacktrace: job.stacktrace,
  };
}

import IORedis, { Redis } from 'ioredis';
import env from '../env';
import logger from '../logger';

/**
 * Redis client singleton for the application
 * Used for caching, rate limiting, and general key-value storage
 *
 * Uses IORedis client with native Redis protocol
 * Works with both local Redis and Upstash Redis native endpoint (rediss://)
 */

let redisClient: Redis | null = null;

/**
 * Get or create the Redis client singleton
 * Returns IORedis client (works with both local and Upstash native endpoints)
 */
export function getRedisClient(): Redis {
  if (!redisClient) {
    // Always use IORedis for native Redis protocol (required for BullMQ)
    // Supports both local Redis and Upstash native endpoint (rediss://)
    logger.info('Initializing Redis client');
    const redisUrl = env.REDIS_URL;
    const options: any = {
      maxRetriesPerRequest: null, // Required for BullMQ
      enableReadyCheck: true,
      lazyConnect: true,
      connectTimeout: 10000, // 10 second timeout
      retryStrategy(times: number) {
        const delay = Math.min(times * 50, 2000);
        return delay;
      },
    };

    redisClient = new IORedis(redisUrl, options);

    redisClient.on('connect', () => {
      logger.info('Redis connected');
    });

    redisClient.on('error', (err) => {
      logger.error({ err }, 'Redis connection error');
    });

    redisClient.on('close', () => {
      logger.warn('Redis connection closed');
    });
  }

  return redisClient as Redis;
}

/**
 * Close the Redis connection gracefully
 */
export async function closeRedis(): Promise<void> {
  if (redisClient) {
    await redisClient.quit();
    redisClient = null;
    logger.info('Redis connection closed');
  }
}

/**
 * Check if Redis is connected and healthy
 */
export async function isRedisHealthy(): Promise<boolean> {
  try {
    const client = getRedisClient();
    const result = await client.ping();
    return result === 'PONG';
  } catch {
    return false;
  }
}

/**
 * Simple cache helpers
 */
export const cache = {
  /**
   * Get a cached value
   */
  async get<T>(key: string): Promise<T | null> {
    const client = getRedisClient();
    const value = await client.get(key);
    if (!value) return null;
    try {
      return JSON.parse(value) as T;
    } catch {
      return value as unknown as T;
    }
  },

  /**
   * Set a cached value with optional TTL (in seconds)
   */
  async set<T>(key: string, value: T, ttlSeconds?: number): Promise<void> {
    const client = getRedisClient();
    const serialized = typeof value === 'string' ? value : JSON.stringify(value);
    if (ttlSeconds) {
      await client.setex(key, ttlSeconds, serialized);
    } else {
      await client.set(key, serialized);
    }
  },

  /**
   * Delete a cached value
   */
  async del(key: string): Promise<void> {
    const client = getRedisClient();
    await client.del(key);
  },

  /**
   * Check if a key exists
   */
  async exists(key: string): Promise<boolean> {
    const client = getRedisClient();
    const result = await client.exists(key);
    return result === 1;
  },

  /**
   * Increment a counter (useful for rate limiting)
   */
  async incr(key: string, ttlSeconds?: number): Promise<number> {
    const client = getRedisClient();
    const value = await client.incr(key);
    if (ttlSeconds && value === 1) {
      await client.expire(key, ttlSeconds);
    }
    return value;
  },
};

export default getRedisClient;

/**
 * Input Sanitization Utilities
 *
 * Security-focused input validation and sanitization functions
 * to prevent injection attacks and ensure data integrity.
 */

/**
 * List of keys that should never be allowed in user input
 * to prevent prototype pollution attacks
 */
const FORBIDDEN_KEYS = new Set([
  '__proto__',
  'prototype',
  'constructor',
  '__defineGetter__',
  '__defineSetter__',
  '__lookupGetter__',
  '__lookupSetter__',
]);

/**
 * Check if a key is safe to use (not a prototype pollution vector)
 */
export function isSafeKey(key: string): boolean {
  return !FORBIDDEN_KEYS.has(key);
}

/**
 * Recursively sanitize an object to remove prototype pollution vectors
 */
export function sanitizeObject<T extends Record<string, unknown>>(obj: T): T {
  if (obj === null || typeof obj !== 'object') {
    return obj;
  }

  if (Array.isArray(obj)) {
    return obj.map((item) =>
      typeof item === 'object' && item !== null
        ? sanitizeObject(item as Record<string, unknown>)
        : item,
    ) as unknown as T;
  }

  const sanitized: Record<string, unknown> = {};

  for (const key of Object.keys(obj)) {
    if (!isSafeKey(key)) {
      console.warn(`[security] Blocked potentially dangerous key: ${key}`);
      continue;
    }

    const value = obj[key];
    if (typeof value === 'object' && value !== null) {
      sanitized[key] = sanitizeObject(value as Record<string, unknown>);
    } else {
      sanitized[key] = value;
    }
  }

  return sanitized as T;
}

/**
 * Sanitize a string to prevent basic XSS attacks
 * Note: This is a basic sanitizer - use a proper library like DOMPurify for HTML content
 */
export function sanitizeString(input: string): string {
  if (typeof input !== 'string') {
    return '';
  }

  return input
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#x27;')
    .replace(/\//g, '&#x2F;');
}

/**
 * Validate that a string matches expected format (alphanumeric + allowed chars)
 */
export function isValidIdentifier(
  input: string,
  options: { allowDashes?: boolean; allowUnderscores?: boolean; maxLength?: number } = {},
): boolean {
  const { allowDashes = true, allowUnderscores = true, maxLength = 128 } = options;

  if (typeof input !== 'string' || input.length === 0 || input.length > maxLength) {
    return false;
  }

  let pattern = '^[a-zA-Z0-9';
  if (allowDashes) pattern += '\\-';
  if (allowUnderscores) pattern += '_';
  pattern += ']+$';

  return new RegExp(pattern).test(input);
}

/**
 * Validate UUID format
 */
export function isValidUUID(input: string): boolean {
  if (typeof input !== 'string') return false;
  const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
  return uuidRegex.test(input);
}

/**
 * Validate email format (basic validation)
 */
export function isValidEmail(input: string): boolean {
  if (typeof input !== 'string' || input.length > 254) return false;
  // RFC 5322 compliant email regex (simplified)
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(input);
}

/**
 * Truncate string to max length safely
 */
export function truncateString(input: string, maxLength: number): string {
  if (typeof input !== 'string') return '';
  if (input.length <= maxLength) return input;
  return input.slice(0, maxLength);
}

/**
 * Safe JSON parse that prevents prototype pollution
 */
export function safeJsonParse<T = unknown>(json: string): T | null {
  try {
    const parsed = JSON.parse(json) as unknown;
    if (typeof parsed === 'object' && parsed !== null) {
      return sanitizeObject(parsed as Record<string, unknown>) as T;
    }
    return parsed as T;
  } catch {
    return null;
  }
}

/**
 * Global Error Handler for Express
 * Provides centralized error handling with proper logging and response formatting
 */
import { Request, Response, NextFunction } from 'express';
import { ZodError } from 'zod';
import { captureException } from '../sentry';
import { logger } from '../logger';
import env from '../env';

/**
 * Custom application error class with status codes
 */
export class AppError extends Error {
  public readonly statusCode: number;
  public readonly isOperational: boolean;
  public readonly code?: string;

  constructor(
    message: string,
    statusCode: number = 500,
    code?: string,
    isOperational: boolean = true,
  ) {
    super(message);
    this.statusCode = statusCode;
    this.code = code;
    this.isOperational = isOperational;
    Error.captureStackTrace(this, this.constructor);
  }
}

// Common error factory functions
export const NotFoundError = (resource: string = 'Resource') =>
  new AppError(`${resource} not found`, 404, 'NOT_FOUND');

export const UnauthorizedError = (message: string = 'Authentication required') =>
  new AppError(message, 401, 'UNAUTHORIZED');

export const ForbiddenError = (message: string = 'Access denied') =>
  new AppError(message, 403, 'FORBIDDEN');

export const BadRequestError = (message: string = 'Invalid request') =>
  new AppError(message, 400, 'BAD_REQUEST');

export const ConflictError = (message: string = 'Resource already exists') =>
  new AppError(message, 409, 'CONFLICT');

export const RateLimitError = (message: string = 'Too many requests') =>
  new AppError(message, 429, 'RATE_LIMIT_EXCEEDED');

/**
 * Error response format
 */
interface ErrorResponse {
  error: string;
  code?: string;
  details?: unknown;
  stack?: string;
}

/**
 * Format Zod validation errors
 */
function formatZodError(error: ZodError): ErrorResponse {
  return {
    error: 'Validation failed',
    code: 'VALIDATION_ERROR',
    details: error.errors.map((err) => ({
      field: err.path.join('.'),
      message: err.message,
    })),
  };
}

/**
 * Check if error is a Prisma unique constraint violation
 */
function isPrismaUniqueConstraintError(error: unknown): boolean {
  return (
    typeof error === 'object' &&
    error !== null &&
    'code' in error &&
    (error as { code: string }).code === 'P2002'
  );
}

/**
 * Global error handling middleware
 * Must be registered last in the middleware chain
 */
export function errorHandler(
  err: Error,
  req: Request,
  res: Response,
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  _next: NextFunction,
): void {
  // Use request context if available (preferred), fallback to extracting from request
  const context = (req as any).context || {
    requestId: (req as { id?: string }).id || 'unknown',
    method: req.method,
    path: req.url,
  };

  // Prepare error context for logging with bound fields from request context
  const errorContext = {
    message: err.message,
    url: req.url,
    method: req.method,
    ...context, // Includes requestId, userId, workspaceId, role, apiKeyId
  };

  // Capture error with Sentry for 5xx errors
  if (!(err instanceof AppError) || err.statusCode >= 500) {
    const sentryId = captureException(err, errorContext);
    if (sentryId) {
      logger.error({ err, sentryId, ...errorContext }, 'Error captured by Sentry');
    }
  }

  // Log error with structured logging using request logger if available
  if (env.NODE_ENV !== 'test') {
    const log = (req as any).log || logger;

    if (err instanceof AppError && err.statusCode < 500) {
      log.warn({ err, ...errorContext }, 'Client error');
    } else {
      log.error({ err, ...errorContext }, 'Server error');
    }
  }

  // Handle Zod validation errors
  if (err instanceof ZodError) {
    res.status(400).json(formatZodError(err));
    return;
  }

  // Handle custom AppError
  if (err instanceof AppError) {
    const response: ErrorResponse = {
      error: err.message,
      code: err.code,
    };

    // Include stack trace in development
    if (env.NODE_ENV === 'development') {
      response.stack = err.stack;
    }

    res.status(err.statusCode).json(response);
    return;
  }

  // Handle Prisma unique constraint errors
  if (isPrismaUniqueConstraintError(err)) {
    res.status(409).json({
      error: 'Resource already exists',
      code: 'DUPLICATE_ENTRY',
    });
    return;
  }

  // Handle JWT errors
  if (err.name === 'JsonWebTokenError') {
    res.status(401).json({
      error: 'Invalid token',
      code: 'INVALID_TOKEN',
    });
    return;
  }

  if (err.name === 'TokenExpiredError') {
    res.status(401).json({
      error: 'Token expired',
      code: 'TOKEN_EXPIRED',
    });
    return;
  }

  // Handle unknown errors (don't leak details in production)
  const isProduction = env.NODE_ENV === 'production';

  const response: ErrorResponse = {
    error: isProduction ? 'Internal server error' : err.message,
    code: 'INTERNAL_ERROR',
  };

  if (!isProduction) {
    response.stack = err.stack;
  }

  res.status(500).json(response);
}

/**
 * Wrapper for async route handlers to catch errors and pass to error middleware
 *
 * @example
 * router.get('/users/:id', asyncHandler(async (req, res) => {
 *   const user = await getUser(req.params.id);
 *   if (!user) throw NotFoundError('User');
 *   res.json(user);
 * }));
 */
export function asyncHandler(
  fn: (req: Request, res: Response, next: NextFunction) => Promise<unknown>,
) {
  return (req: Request, res: Response, next: NextFunction): void => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
}

/**
 * 404 handler for unmatched routes
 */
export function notFoundHandler(req: Request, res: Response): void {
  res.status(404).json({
    error: `Route ${req.method} ${req.url} not found`,
    code: 'ROUTE_NOT_FOUND',
  });
}

/**
 * Rate limiting middleware for chat endpoint
 * In-memory token bucket - replace with Redis for production
 */
import type { Request, Response, NextFunction } from 'express';

// Chat-specific rate limits (more generous than /run endpoint)
const WINDOW_MS = 60_000; // 1 minute
const MAX_REQUESTS_PER_WINDOW = 30; // 30 chat messages per minute per workspace

type Key = string;

const buckets = new Map<Key, { windowStart: number; count: number }>();

function getClientKey(req: Request): string {
  // Prefer workspace ID for multi-tenant isolation
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const auth = (req as any).auth;
  if (auth?.workspaceId) return `ws:${auth.workspaceId}`;

  // Fallback to user ID
  if (auth?.userId) return `user:${auth.userId}`;

  // Last resort: IP address
  return `ip:${req.ip}`;
}

/**
 * Rate limit middleware for chat endpoint
 * Enforces per-workspace rate limiting using token bucket algorithm
 */
export function rateLimitChat(req: Request, res: Response, next: NextFunction) {
  const key = getClientKey(req);
  const now = Date.now();
  const bucket = buckets.get(key);

  // Reset bucket if window expired
  if (!bucket || now - bucket.windowStart > WINDOW_MS) {
    buckets.set(key, { windowStart: now, count: 1 });
    return next();
  }

  // Check if rate limit exceeded
  if (bucket.count >= MAX_REQUESTS_PER_WINDOW) {
    const retryAfter = Math.ceil((bucket.windowStart + WINDOW_MS - now) / 1000);
    res.setHeader('Retry-After', retryAfter);
    return res.status(429).json({
      error: 'RATE_LIMITED',
      message: `Too many chat requests. Please retry in ${retryAfter} seconds.`,
      retryAfter,
    });
  }

  // Increment count and proceed
  bucket.count += 1;
  return next();
}

/**
 * Rate limiting middleware for metrics endpoint
 * Prevents scrape abuse while allowing legitimate Prometheus scraping
 */
import type { Request, Response, NextFunction } from 'express';

// Metrics-specific rate limits (more generous than API endpoints)
// Prometheus typically scrapes every 15-60 seconds
const WINDOW_MS = 60_000; // 1 minute
const MAX_REQUESTS_PER_WINDOW = 10; // 10 scrapes per minute (generous for 15s scrape interval)

type Key = string;

const buckets = new Map<Key, { windowStart: number; count: number }>();

function getClientKey(req: Request): string {
  // Prefer admin API key ID if available
  const auth = (req as any).auth;
  if (auth?.apiKeyId) return `admin:${auth.apiKeyId}`;

  // Fallback to IP address for unauthenticated requests (will be rejected anyway)
  return `ip:${req.ip}`;
}

/**
 * Rate limit middleware for metrics endpoint
 * Enforces per-scraper rate limiting using token bucket algorithm
 *
 * Configuration:
 * - 10 requests per minute per admin API key
 * - Suitable for Prometheus scrape intervals of 15s or longer
 * - Returns 429 with Retry-After header when limit exceeded
 */
export function rateLimitMetrics(req: Request, res: Response, next: NextFunction) {
  const key = getClientKey(req);
  const now = Date.now();
  const bucket = buckets.get(key);

  // Reset bucket if window expired
  if (!bucket || now - bucket.windowStart > WINDOW_MS) {
    buckets.set(key, { windowStart: now, count: 1 });
    return next();
  }

  // Check if rate limit exceeded
  if (bucket.count >= MAX_REQUESTS_PER_WINDOW) {
    const retryAfter = Math.ceil((bucket.windowStart + WINDOW_MS - now) / 1000);
    res.setHeader('Retry-After', retryAfter);
    return res.status(429).json({
      error: 'RATE_LIMITED',
      message: `Too many metrics requests. Please retry in ${retryAfter} seconds.`,
      retryAfter,
      limit: MAX_REQUESTS_PER_WINDOW,
      window: '1 minute',
    });
  }

  // Increment count and proceed
  bucket.count += 1;
  return next();
}

/**
 * Reset rate limit buckets (for testing only)
 * @internal
 */
export function resetRateLimitBuckets() {
  buckets.clear();
}

import type { Request, Response, NextFunction } from 'express';

// In-memory token bucket as a starting point; replace with Redis-based limiter in prod.
const WINDOW_MS = 60_000; // 1 minute
const MAX_REQUESTS_PER_WINDOW = 60;

type Key = string;

const buckets = new Map<Key, { windowStart: number; count: number }>();

function getClientKey(req: Request): string {
  // Prefer auth principal or workspace id if available; fallback to IP.
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const principal = (req as any).authPrincipal;
  if (principal?.workspaceId) return `ws:${principal.workspaceId}`;
  return `ip:${req.ip}`;
}

export function rateLimitRun(req: Request, res: Response, next: NextFunction) {
  const key = getClientKey(req);
  const now = Date.now();
  const bucket = buckets.get(key);

  if (!bucket || now - bucket.windowStart > WINDOW_MS) {
    buckets.set(key, { windowStart: now, count: 1 });
    return next();
  }

  if (bucket.count >= MAX_REQUESTS_PER_WINDOW) {
    res.setHeader('Retry-After', Math.ceil((bucket.windowStart + WINDOW_MS - now) / 1000));
    return res.status(429).json({
      error: 'RATE_LIMITED',
      message: 'Too many run requests; please retry later.',
    });
  }

  bucket.count += 1;
  return next();
}

/**
 * Request Context Middleware
 * Propagates request ID and authentication context into logs and error handlers
 *
 * Flow:
 * 1. Extract request ID from pino-http (already set)
 * 2. Attach auth context from authentication middleware
 * 3. Create child logger with bound context
 * 4. Make context available throughout request lifecycle
 */
import { Request, Response, NextFunction } from 'express';
import { logger } from '../logger';
import '../types/auth';

/**
 * Request context that should be propagated through logs and errors
 */
export interface RequestContext {
  requestId: string;
  userId?: string;
  workspaceId?: string;
  role?: string;
  apiKeyId?: string;
  method: string;
  path: string;
  ip?: string;
}

/**
 * Extended Request type with context and logger
 */
declare global {
  namespace Express {
    interface Request {
      context?: RequestContext;
      log?: any; // Use any for Pino logger to avoid complex type issues
    }
  }
}

/**
 * Extract authentication context from request
 */
function extractAuthContext(req: Request): Partial<RequestContext> {
  const auth = req.auth;

  if (!auth) {
    return {};
  }

  const context: Partial<RequestContext> = {};

  // User authentication
  if (auth.sub) {
    context.userId = auth.sub;
  }

  // Workspace context
  if (auth.workspaceId) {
    context.workspaceId = auth.workspaceId;
  }

  // Role information
  if (auth.role) {
    context.role = auth.role;
  }

  // API key authentication
  if (auth.apiKey && auth.apiKeyId) {
    context.apiKeyId = auth.apiKeyId;
  }

  // Admin authentication
  if (auth.roles && auth.roles.includes('admin')) {
    context.role = 'admin';
  }

  return context;
}

/**
 * Request context middleware
 *
 * Usage: app.use(requestContext)
 *
 * Must be placed AFTER:
 * - httpLogger (pino-http) - provides request ID
 * - authentication middleware - provides auth context
 *
 * Provides:
 * - req.context - structured context object
 * - req.log - child logger with bound context
 */
export function requestContext(req: Request, _res: Response, next: NextFunction): void {
  // Extract request ID from pino-http
  const requestId = (req.id || (req as any).log?.bindings?.()?.reqId || 'unknown') as string;

  // Build context from request metadata
  const authContext = extractAuthContext(req);

  const context: RequestContext = {
    requestId,
    method: req.method,
    path: req.path || req.url,
    ip: req.ip || req.socket.remoteAddress,
    ...authContext,
  };

  // Attach context to request
  req.context = context;

  // Create child logger with bound context for this request
  // All logs using req.log will automatically include this context
  req.log = logger.child({
    requestId: context.requestId,
    ...(context.userId && { userId: context.userId }),
    ...(context.workspaceId && { workspaceId: context.workspaceId }),
    ...(context.role && { role: context.role }),
    ...(context.apiKeyId && { apiKeyId: context.apiKeyId }),
  }) as any;

  next();
}

/**
 * Get request context from Express request
 * Useful in services/controllers that receive the request object
 */
export function getRequestContext(req: Request): RequestContext | undefined {
  return req.context;
}

/**
 * Get request logger with bound context
 * Useful in services/controllers that receive the request object
 */
export function getRequestLogger(req: Request): any {
  return req.log || logger;
}

/**
 * Refresh request context after authentication
 * Call this in authentication middleware after setting req.auth
 * to update the logger with auth context
 */
export function refreshRequestContext(req: Request): void {
  if (!req.context) {
    return; // Context not initialized yet
  }

  const authContext = extractAuthContext(req);

  // Update context with auth info
  Object.assign(req.context, authContext);

  // Recreate child logger with updated context
  req.log = logger.child({
    requestId: req.context.requestId,
    ...(req.context.userId && { userId: req.context.userId }),
    ...(req.context.workspaceId && { workspaceId: req.context.workspaceId }),
    ...(req.context.role && { role: req.context.role }),
    ...(req.context.apiKeyId && { apiKeyId: req.context.apiKeyId }),
  }) as any;
}

/**
 * Metrics-specific authentication middleware
 * Requires ADMIN_API_KEY for access to sensitive observability data
 */
import { Request, Response, NextFunction } from 'express';
import env from '../env';
import { logger } from '../logger';

/**
 * Middleware to require admin API key for metrics endpoint
 *
 * Usage: app.get('/metrics', requireMetricsAuth, metricsHandler)
 *
 * Security notes:
 * - Protects against information leakage (workspaces, users, system internals)
 * - Rate limited separately to prevent scrape abuse
 * - Used by Prometheus scraper with dedicated service account
 *
 * Configuration:
 * - Set ADMIN_API_KEY in environment (min 32 chars)
 * - Use x-api-key header or api_key query param
 * - Example: curl http://localhost:4000/metrics -H "x-api-key: <admin-key>"
 */
export function requireMetricsAuth(req: Request, res: Response, next: NextFunction) {
  const apiKeyHeader = (req.headers['x-api-key'] as string) || '';
  const apiKeyQuery = (req.query?.api_key as string) || '';
  const providedKey = apiKeyHeader || apiKeyQuery;

  const adminApiKey = env.ADMIN_API_KEY;

  // Check if admin API key is configured
  if (!adminApiKey) {
    logger.error('ADMIN_API_KEY not configured - metrics endpoint disabled');
    return res.status(503).json({
      error: 'metrics_unavailable',
      message: 'Metrics endpoint is not configured. Set ADMIN_API_KEY environment variable.',
      code: 'METRICS_NOT_CONFIGURED',
    });
  }

  // Check if API key provided
  if (!providedKey) {
    logger.warn({ ip: req.ip, path: req.path }, 'Metrics access attempt without credentials');
    return res.status(401).json({
      error: 'missing_credentials',
      message: 'Admin API key required. Provide via x-api-key header or api_key query parameter.',
      code: 'MISSING_CREDENTIALS',
    });
  }

  // Verify API key matches
  if (providedKey !== adminApiKey) {
    logger.warn({ ip: req.ip, path: req.path }, 'Invalid admin API key attempt');
    return res.status(403).json({
      error: 'invalid_credentials',
      message: 'Invalid admin API key',
      code: 'INVALID_CREDENTIALS',
    });
  }

  // Success - log for audit trail
  logger.info({ ip: req.ip, path: req.path }, 'Metrics access granted');

  // Attach auth info for rate limiter to use
  (req as any).auth = {
    apiKey: true,
    apiKeyId: 'admin',
    role: 'admin',
    roles: ['admin'],
  };

  return next();
}

import { Request, Response, NextFunction } from 'express';
import '../types/auth'; // Import to register global types
import { ROLES, ROLE_HIERARCHY } from '../types/auth';
import { logger } from '../logger';

/**
 * Role hierarchy levels - higher index = more permissions
 * service role is equivalent to member (limited access)
 */
const ROLE_LEVELS: Record<string, number> = {
  viewer: 0,
  service: 1, // API keys get service role - between viewer and member
  member: 2,
  user: 2, // alias for member
  agent: 2, // alias for member
  manager: 3,
  admin: 4,
  owner: 4, // alias for admin
  super_admin: 5,
};

function getRoleLevel(role: string): number {
  const normalized = role.toLowerCase();
  return ROLE_LEVELS[normalized] ?? -1;
}

/**
 * requireRole middleware: check that the authenticated principal has at least one of the allowed roles.
 *
 * SECURITY NOTES:
 * - API keys do NOT automatically bypass role checks
 * - API keys have 'service' role which must be explicitly allowed
 * - Anonymous users are always rejected
 */
export function requireRole(...allowed: string[]) {
  return (req: Request, res: Response, next: NextFunction) => {
    try {
      const auth = req.auth || {};

      // Must be authenticated first
      if (!auth || auth.anonymous) {
        return res.status(401).json({
          error: 'unauthorized',
          message: 'Authentication required',
          code: 'AUTH_REQUIRED',
        });
      }

      // Collect all roles from auth context
      const roles: string[] = [];
      if (auth.role && typeof auth.role === 'string') roles.push(auth.role);
      if (Array.isArray(auth.roles)) roles.push(...auth.roles);

      if (roles.length === 0) {
        logger.warn({ userId: auth.sub, apiKey: auth.apiKey }, 'No roles assigned');
        return res.status(403).json({
          error: 'forbidden',
          message: 'No roles assigned to user',
          code: 'NO_ROLES',
        });
      }

      // Normalize to lower-case for comparison
      const normalized = roles.map((r) => (r || '').toLowerCase());
      const allowedNorm = allowed.map((r) => (r || '').toLowerCase());

      // Check if user has any of the allowed roles
      const ok = normalized.some((r) => allowedNorm.includes(r));
      if (!ok) {
        logger.warn(
          { userId: auth.sub, userRoles: roles, requiredRoles: allowed },
          'Insufficient role',
        );
        return res.status(403).json({
          error: 'forbidden',
          message: `Required role(s): ${allowed.join(', ')}`,
          code: 'INSUFFICIENT_ROLE',
          required: allowed,
        });
      }

      return next();
    } catch (err: unknown) {
      logger.error({ error: err }, 'requireRole error');
      return res.status(500).json({ error: 'server_error' });
    }
  };
}

/**
 * requireMinRole middleware: check that user has at least the minimum role level (hierarchical)
 *
 * SECURITY NOTES:
 * - Uses hierarchical comparison: owner > admin > manager > member > service > viewer
 * - API keys have 'service' role level
 */
export function requireMinRole(minRole: string) {
  return (req: Request, res: Response, next: NextFunction) => {
    try {
      const auth = req.auth || {};

      // Must be authenticated first
      if (!auth || auth.anonymous) {
        return res.status(401).json({
          error: 'unauthorized',
          message: 'Authentication required',
          code: 'AUTH_REQUIRED',
        });
      }

      // Get user's roles
      const roles: string[] = [];
      if (auth.role && typeof auth.role === 'string') roles.push(auth.role);
      if (Array.isArray(auth.roles)) roles.push(...auth.roles);

      if (roles.length === 0) {
        return res.status(403).json({
          error: 'forbidden',
          message: 'No roles assigned to user',
          code: 'NO_ROLES',
        });
      }

      // Get the highest role level the user has
      const userMaxLevel = Math.max(...roles.map(getRoleLevel));
      const requiredLevel = getRoleLevel(minRole);

      if (requiredLevel < 0) {
        logger.error({ minRole }, 'Invalid minimum role specified');
        return res
          .status(500)
          .json({ error: 'server_error', message: 'Invalid role configuration' });
      }

      if (userMaxLevel < requiredLevel) {
        logger.warn(
          { userId: auth.sub, userRoles: roles, minRole, userLevel: userMaxLevel, requiredLevel },
          'Insufficient role level',
        );
        return res.status(403).json({
          error: 'forbidden',
          message: `Minimum required role: ${minRole}`,
          code: 'INSUFFICIENT_ROLE',
          required: minRole,
        });
      }

      return next();
    } catch (err: unknown) {
      logger.error({ error: err }, 'requireMinRole error');
      return res.status(500).json({ error: 'server_error' });
    }
  };
}

/**
 * requireAdmin helper: check if user has admin or super_admin role
 */
export function requireAdmin() {
  return requireMinRole(ROLES.ADMIN);
}

/**
 * requireServiceOrAbove: allows API keys (service role) or any user role
 * Use this for endpoints that should be accessible to both API keys and authenticated users
 */
export function requireServiceOrAbove() {
  return requireMinRole('service');
}

// Re-export ROLES for convenience
export { ROLES, ROLE_HIERARCHY };

export default requireRole;

import type { Request, Response, NextFunction } from 'express';
import type { ZodSchema } from 'zod';

export function validateBody<T>(schema: ZodSchema<T>) {
  return (req: Request, res: Response, next: NextFunction) => {
    const result = schema.safeParse(req.body);

    if (!result.success) {
      const issues = result.error.issues.map((issue) => ({
        path: issue.path.join('.'),
        message: issue.message,
        code: issue.code,
      }));

      // Centralized error shape for validation
      return res.status(400).json({
        error: 'INVALID_REQUEST_BODY',
        issues,
      });
    }

    // Attach parsed, typed body to request for downstream consumers
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    (req as any).validatedBody = result.data;
    return next();
  };
}

import { Queue, QueueEvents } from 'bullmq';
import { getRedisClient } from './lib/redis';
import {
  queueWaitingGauge,
  queueActiveGauge,
  queueFailedGauge,
  dlqDepthGauge,
  jobFailureCounter,
} from './metrics';
import logger from './logger';
import env from './env';

// Lazy connection - only connect when queues are actually used
let connection: ReturnType<typeof getRedisClient> | null = null;
function getConnection() {
  if (!connection) {
    connection = getRedisClient();
  }
  return connection;
}

// Define job types
export type IngestJobData = {
  tenantId?: string;
  workspaceId?: string;
  documentId?: string;
  documents?: unknown[];
  ingestionId?: string;
  source?: string;
  content?: string;
  metadata?: Record<string, unknown>;
};

export type EmailJobData = {
  to: string | string[];
  subject: string;
  html?: string;
  text?: string;
  templateId?: string;
  templateData?: Record<string, unknown>;
};

export type JobData = IngestJobData | EmailJobData;

// Queue definitions - use lazy getter
function createIngestQueue() {
  return new Queue<IngestJobData>('ingest', {
    connection: getConnection(),
    defaultJobOptions: {
      attempts: 5, // Increased from 3 to give more retry opportunities
      backoff: {
        type: 'exponential',
        delay: 2000, // Start with 2s delay
      },
      removeOnComplete: 100, // Keep last 100 completed jobs
      removeOnFail: false, // Never auto-remove failed jobs - they go to DLQ
    },
  });
}

// Dead Letter Queue for permanently failed ingestion jobs
function createIngestDLQ() {
  return new Queue<IngestJobData>('ingest-dlq', {
    connection: getConnection(),
    defaultJobOptions: {
      removeOnComplete: false, // Keep all DLQ entries for investigation
      removeOnFail: false,
    },
  });
}

function createEmailQueue() {
  return new Queue<EmailJobData>('email', {
    connection: getConnection(),
    defaultJobOptions: {
      attempts: 3,
      backoff: {
        type: 'exponential',
        delay: 2000,
      },
      removeOnComplete: 50,
      removeOnFail: 200,
    },
  });
}

// Lazy queue instances
let _ingestQueue: Queue<IngestJobData> | null = null;
let _ingestDLQ: Queue<IngestJobData> | null = null;
let _emailQueue: Queue<EmailJobData> | null = null;
let _ingestEvents: QueueEvents | null = null;
let _emailEvents: QueueEvents | null = null;

export const ingestQueue = new Proxy({} as Queue<IngestJobData>, {
  get(_target, prop) {
    if (!_ingestQueue) _ingestQueue = createIngestQueue();
    return Reflect.get(_ingestQueue, prop);
  },
});

export const ingestDLQ = new Proxy({} as Queue<IngestJobData>, {
  get(_target, prop) {
    if (!_ingestDLQ) _ingestDLQ = createIngestDLQ();
    return Reflect.get(_ingestDLQ, prop);
  },
});

export const emailQueue = new Proxy({} as Queue<EmailJobData>, {
  get(_target, prop) {
    if (!_emailQueue) _emailQueue = createEmailQueue();
    return Reflect.get(_emailQueue, prop);
  },
});

// Queue events for logging - only create when accessed
function getIngestEvents() {
  if (!_ingestEvents) {
    _ingestEvents = new QueueEvents('ingest', { connection: getConnection() });
  }
  return _ingestEvents;
}

function getEmailEvents() {
  if (!_emailEvents) {
    _emailEvents = new QueueEvents('email', { connection: getConnection() });
  }
  return _emailEvents;
}

const ingestEvents = getIngestEvents();
const emailEvents = getEmailEvents();

ingestEvents.on('completed', ({ jobId }) => {
  logger.debug({ jobId, queue: 'ingest' }, 'Job completed');
});

ingestEvents.on('failed', async ({ jobId, failedReason }) => {
  logger.error({ jobId, queue: 'ingest', reason: failedReason }, 'Job failed');

  // Increment failure counter
  const job = await ingestQueue.getJob(jobId);
  if (job) {
    const attemptsMade = job.attemptsMade || 0;
    const maxAttempts = job.opts?.attempts || 5;
    const isFinal = attemptsMade >= maxAttempts;

    // Extract failure reason category
    const reason = extractFailureReason(failedReason);
    jobFailureCounter.inc({ queue: 'ingest', reason, final: isFinal ? 'true' : 'false' });

    // Move to DLQ if all retries exhausted
    if (isFinal) {
      logger.warn(
        {
          jobId,
          workspaceId: job.data.workspaceId,
          ingestionId: job.data.ingestionId,
          attempts: attemptsMade,
          reason: failedReason,
        },
        'Job exhausted all retries, moving to DLQ',
      );

      try {
        await ingestDLQ.add('dlq-entry', {
          ...job.data,
          metadata: {
            ...job.data.metadata,
            originalJobId: jobId,
            failedReason,
            attemptsMade,
            failedAt: new Date().toISOString(),
          },
        });
        logger.info({ jobId, dlqJobId: jobId }, 'Job moved to DLQ');
      } catch (dlqError) {
        logger.error({ jobId, error: dlqError }, 'Failed to move job to DLQ');
      }
    }
  }
});

// Track retry attempts
ingestEvents.on('retries-exhausted', ({ jobId }) => {
  logger.error({ jobId, queue: 'ingest' }, 'Job retries exhausted');
});

/**
 * Extract categorized failure reason from error message
 */
function extractFailureReason(errorMessage: string): string {
  if (!errorMessage) return 'unknown';

  const msg = errorMessage.toLowerCase();
  if (msg.includes('workspace not found')) return 'workspace_not_found';
  if (msg.includes('qdrant')) return 'qdrant_error';
  if (msg.includes('database') || msg.includes('prisma')) return 'database_error';
  if (msg.includes('timeout')) return 'timeout';
  if (msg.includes('validation')) return 'validation_error';

  return 'unknown';
}

emailEvents.on('completed', ({ jobId }) => {
  logger.debug({ jobId, queue: 'email' }, 'Email job completed');
});

emailEvents.on('failed', ({ jobId, failedReason }) => {
  logger.error({ jobId, queue: 'email', reason: failedReason }, 'Email job failed');
});

// Helper functions to add jobs
export async function addIngestJob(
  data: IngestJobData,
  options?: { priority?: number; delay?: number },
) {
  return ingestQueue.add('ingest', data, {
    priority: options?.priority,
    delay: options?.delay,
  });
}

export async function addEmailJob(
  data: EmailJobData,
  options?: { priority?: number; delay?: number },
) {
  return emailQueue.add('send', data, {
    priority: options?.priority,
    delay: options?.delay,
  });
}

// Schedule a recurring job (e.g., daily cleanup)
export async function scheduleRecurringJob(
  queue: Queue,
  name: string,
  data: Record<string, unknown>,
  pattern: string, // cron pattern
) {
  // Remove existing scheduled job
  const repeatableJobs = await queue.getRepeatableJobs();
  const existing = repeatableJobs.find((job) => job.name === name);
  if (existing) {
    await queue.removeRepeatableByKey(existing.key);
  }

  // Add new scheduled job
  return queue.add(name, data, {
    repeat: { pattern },
  });
}

// Poll and update metrics periodically
async function updateMetrics() {
  try {
    const ingestCounts = await ingestQueue.getJobCounts();
    const emailCounts = await emailQueue.getJobCounts();
    const dlqCounts = await ingestDLQ.getJobCounts();

    queueWaitingGauge.set({ queue: 'ingest' }, ingestCounts.waiting || 0);
    queueActiveGauge.set({ queue: 'ingest' }, ingestCounts.active || 0);
    queueFailedGauge.set({ queue: 'ingest' }, ingestCounts.failed || 0);

    queueWaitingGauge.set({ queue: 'email' }, emailCounts.waiting || 0);
    queueActiveGauge.set({ queue: 'email' }, emailCounts.active || 0);
    queueFailedGauge.set({ queue: 'email' }, emailCounts.failed || 0);

    // Track DLQ depth
    dlqDepthGauge.set(
      { queue: 'ingest' },
      (dlqCounts.waiting || 0) + (dlqCounts.active || 0) + (dlqCounts.completed || 0),
    );
  } catch (e) {
    // ignore metrics errors
  }
}

// Track the metrics interval for cleanup
let metricsInterval: NodeJS.Timeout | null = null;

/**
 * Determine if queue metrics should be enabled based on server role and explicit flag
 */
function shouldEnableQueueMetrics(): boolean {
  // Explicit flag takes precedence
  if (env.ENABLE_QUEUE_METRICS) {
    return true;
  }

  // Auto-enable for worker and all roles
  if (env.SERVER_ROLE === 'worker' || env.SERVER_ROLE === 'all') {
    return true;
  }

  // Disable for pure API servers and test environment
  if (env.NODE_ENV === 'test') {
    return false;
  }

  return false;
}

/**
 * Start the queue metrics polling interval
 * Only starts if enabled by server role or explicit flag
 */
export function startQueueMetrics(): void {
  if (metricsInterval) {
    logger.debug('Queue metrics already running');
    return;
  }

  if (!shouldEnableQueueMetrics()) {
    logger.debug(
      { serverRole: env.SERVER_ROLE, enableFlag: env.ENABLE_QUEUE_METRICS },
      'Queue metrics disabled for this server role',
    );
    return;
  }

  metricsInterval = setInterval(() => {
    void updateMetrics();
  }, 5000);

  // Ensure interval doesn't prevent Node from exiting
  metricsInterval.unref();

  logger.info({ serverRole: env.SERVER_ROLE }, 'Queue metrics polling started');
}

/**
 * Stop the queue metrics polling interval
 */
export function stopQueueMetrics(): void {
  if (metricsInterval) {
    clearInterval(metricsInterval);
    metricsInterval = null;
    logger.debug('Queue metrics polling stopped');
  }
}

// Graceful shutdown
export async function closeQueues(): Promise<void> {
  // Stop metrics polling first
  stopQueueMetrics();

  await Promise.all([
    ingestQueue.close(),
    ingestDLQ.close(),
    emailQueue.close(),
    ingestEvents.close(),
    emailEvents.close(),
  ]);
  logger.info('Queues closed');
}

/**
 * Graceful shutdown handler for the entire queue system
 * Call this on process exit signals
 */
export async function gracefulShutdown(): Promise<void> {
  logger.info('Queue system shutting down...');
  await closeQueues();
}

// Track whether shutdown handlers have been registered
let shutdownHandlersRegistered = false;

/**
 * Register shutdown handlers for graceful queue cleanup
 * Call this explicitly from your main entry point
 * Opt-in pattern prevents duplicate handlers and test interference
 */
export function registerQueueShutdownHandlers(): void {
  if (shutdownHandlersRegistered) {
    logger.debug('Queue shutdown handlers already registered');
    return;
  }

  // Don't register in test environment
  if (env.NODE_ENV === 'test') {
    logger.debug('Skipping shutdown handler registration in test environment');
    return;
  }

  // Handle process termination signals
  const shutdownSignals: NodeJS.Signals[] = ['SIGTERM', 'SIGINT'];

  shutdownSignals.forEach((signal) => {
    process.on(signal, () => {
      logger.info({ signal }, 'Received shutdown signal');
      void gracefulShutdown().then(() => {
        process.exit(0);
      });
    });
  });

  // Handle uncaught exceptions - close queues before crashing
  process.on('uncaughtException', (error) => {
    logger.error({ error }, 'Uncaught exception, shutting down queues');
    void gracefulShutdown().finally(() => {
      process.exit(1);
    });
  });

  shutdownHandlersRegistered = true;
  logger.info('Queue shutdown handlers registered');
}

export default {
  ingestQueue,
  ingestDLQ,
  emailQueue,
  addIngestJob,
  addEmailJob,
  scheduleRecurringJob,
  closeQueues,
  gracefulShutdown,
  registerQueueShutdownHandlers,
  startQueueMetrics,
  stopQueueMetrics,
  connection,
};

